use std::path::Path;

use serde::{Deserialize, Serialize};

use crate::core::{ProjectContext, Scene};

const PROJECT_PATH: &str = "kinematic/project.ron";

/// Factory generated by [`crate::scene`] with resolution and margin in pixels.
pub type SceneFactory = fn(&ProjectContext, (u32, u32), (u32, u32)) -> Scene;

#[derive(Clone, Copy, Debug, Deserialize, PartialEq, Serialize)]
#[serde(default)]
pub(crate) struct ProjectSettings {
    pub(crate) resolution: (u32, u32),
    pub(crate) fps: u32,
    pub(crate) margin: (u32, u32),
}

impl Default for ProjectSettings {
    fn default() -> Self {
        Self {
            resolution: (1280, 720),
            fps: 60,
            margin: (0, 0),
        }
    }
}

impl ProjectSettings {
    pub(crate) fn load(context: &ProjectContext) -> std::io::Result<Self> {
        let path = context.resolve(PROJECT_PATH)?;
        match std::fs::read_to_string(path) {
            Ok(text) => {
                let settings = ron::from_str(&text).map_err(std::io::Error::other)?;
                if !Self::is_valid(&settings) {
                    return Err(std::io::Error::other(
                        "Project settings contain invalid values.",
                    ));
                }
                Ok(settings)
            }
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(Self::default()),
            Err(error) => Err(error),
        }
    }

    pub(crate) fn save(&self, context: &ProjectContext) -> std::io::Result<()> {
        write(self, &context.resolve(PROJECT_PATH)?)
            .map_err(|e| std::io::Error::other(e.to_string()))
    }

    pub(crate) fn is_valid(settings: &Self) -> bool {
        settings.resolution.0 > 0
            && settings.resolution.1 > 0
            && settings.resolution.0.is_multiple_of(2)
            && settings.resolution.1.is_multiple_of(2)
            && settings.fps > 0
            && settings.resolution.0 <= 8192
            && settings.resolution.1 <= 8192
            && settings.fps <= 1000
            && settings.margin.0 < settings.resolution.0 / 2
            && settings.margin.1 < settings.resolution.1 / 2
    }
}

pub(crate) struct Project {
    pub(crate) name: String,
    pub(crate) context: ProjectContext,
    pub(crate) settings: ProjectSettings,
    pub(crate) scenes: Vec<SceneFactory>,
}

impl Project {
    pub(crate) fn new(name: &str, scenes: Vec<SceneFactory>) -> Self {
        Self::new_in(
            ProjectContext::new(".").expect("Project directory must exist."),
            name,
            scenes,
        )
        .expect("Native project settings must be valid.")
    }

    pub(crate) fn new_in(
        context: ProjectContext,
        name: &str,
        scenes: Vec<SceneFactory>,
    ) -> std::io::Result<Self> {
        Ok(Self {
            name: name.to_owned(),
            settings: ProjectSettings::load(&context)?,
            context,
            scenes,
        })
    }

    pub(crate) fn validate(&self) {
        assert!(
            !self.scenes.is_empty(),
            "Project must contain at least one scene."
        );
        assert!(ProjectSettings::is_valid(&self.settings));
    }
}

fn write(settings: &ProjectSettings, path: &Path) -> Result<(), Box<dyn std::error::Error>> {
    if let Some(directory) = path.parent() {
        std::fs::create_dir_all(directory)?;
    }

    let contents = ron::ser::to_string_pretty(settings, ron::ser::PrettyConfig::default())?;
    let expected = std::fs::read(path).ok();
    crate::core::atomic_write(
        path,
        format!("{contents}\n").as_bytes(),
        expected.as_deref(),
    )?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn project_settings_have_editor_defaults() {
        assert_eq!(
            ProjectSettings::default(),
            ProjectSettings {
                resolution: (1280, 720),
                fps: 60,
                margin: (0, 0),
            }
        );
    }

    #[test]
    fn project_settings_require_exportable_values() {
        assert!(ProjectSettings::is_valid(&ProjectSettings::default()));
        assert!(!ProjectSettings::is_valid(&ProjectSettings {
            resolution: (1279, 720),
            fps: 60,
            margin: (64, 64),
        }));
        assert!(!ProjectSettings::is_valid(&ProjectSettings {
            resolution: (1280, 720),
            fps: 0,
            margin: (64, 64),
        }));
    }

    #[test]
    fn project_settings_are_written_as_readable_ron() {
        let directory = std::env::temp_dir().join(format!(
            "kinematic-project-settings-test-{}-{:?}",
            std::process::id(),
            std::thread::current().id()
        ));
        let path = directory.join("project.ron");
        let settings = ProjectSettings {
            resolution: (1920, 1080),
            fps: 30,
            margin: (64, 64),
        };

        write(&settings, &path).unwrap();

        let contents = std::fs::read_to_string(&path).unwrap();
        let loaded: ProjectSettings = ron::from_str(&contents).unwrap();
        assert_eq!(loaded, settings);
        assert!(contents.contains("resolution: (1920, 1080)"));
        assert!(contents.contains("fps: 30"));

        std::fs::remove_dir_all(directory).unwrap();
    }
}
